@router.get('/api/patients/scans/{scan_id}/dicom')
async def stream_medical_scan(
    scan_id: int,
    db: AsyncSession = Depends(get_async_session),
    user: User = Depends(get_current_user)
):
    stmt = select(MedicalScan).where(
        MedicalScan.id == scan_id,
        or_(MedicalScan.patient_id == user.id, MedicalScan.physician_id == user.id)
    )
    result = await db.execute(stmt)
    scan = result.scalar_one_or_none()
